   106			if err := os.WriteFile(filepath.Join(entireDir, "settings.json"),
   107				[]byte("{\"external_agents\": true}\n"), 0o644); err != nil {
   108				t.Fatalf("write external_agents setting: %v", err)
   109			}
   110		}
   111	
   112		entire.Enable(t, dir, agent.EntireAgent())
   113		if agent.Name() == "gemini-cli" {
   114			setupGeminiTestHome(t, dir)
   115		}
   116		if agent.Name() == "factoryai-droid" {
   117			if err := configureDroidRepoSettings(dir); err != nil {
   118				t.Fatalf("configure droid repo settings: %v", err)
   119			}
   120		}
   121		// commit_linking=always ensures the prepare-commit-msg hook adds the
   122		// Entire-Checkpoint trailer unconditionally. This is needed because
   123		// interactive agents run inside tmux (CanPromptInteractively()=true) but
   124		// can't respond to prompts, and content detection may fail on the first
   125		// checkpoint when no shadow branch exists yet. Prompt-mode agents still
   126		// exercise the !CanPromptInteractively() fast path since they have no TTY
   127		// regardless of this setting.
   128		PatchSettings(t, dir, map[string]any{"log_level": "debug", "commit_linking": "always"})
   129		ApplySuiteCheckpointsMode(t, dir)
   130	
   131		// Copilot CLI blocks on a "No copilot instructions found" notice in fresh
   132		// repos that lack .github/copilot-instructions.md, preventing the interactive
   133		// prompt from appearing.
   134		if agent.Name() == "copilot-cli" {
   135			ghDir := filepath.Join(dir, ".github")
   136			if err := os.MkdirAll(ghDir, 0o755); err != nil {
   137				t.Fatalf("create .github dir: %v", err)
   138			}
   139			if err := os.WriteFile(filepath.Join(ghDir, "copilot-instructions.md"), []byte("# E2E Test\n"), 0o644); err != nil {
   140				t.Fatalf("write copilot-instructions.md: %v", err)
   141			}
   142		}
   143	
   144		// OpenCode's non-interactive mode auto-rejects external_directory permission
   145		// since there's no user to prompt. Write a config to allow it.
   146		if agent.Name() == "opencode" {
   147			cfg := `{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}}`
   148			if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
   149				cfg = fmt.Sprintf(`{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}, "provider": {"anthropic": {"options": {"apiKey": %q}}}}`, key)
   150			}
   151			if err := os.WriteFile(filepath.Join(dir, "opencode.json"), []byte(cfg+"\n"), 0o644); err != nil {
   152				t.Fatalf("write opencode.json: %v", err)
   153			}
   154		}
   155	
   156		// Create artifact dir eagerly so console.log is written to disk
   157		// incrementally. Even if the test is killed by a global timeout,
   158		// partial output survives.
   159		artDir := artifactDir(t)
   160		consoleLog, err := os.Create(filepath.Join(artDir, "console.log"))
   161		if err != nil {
   162			t.Fatalf("create console.log: %v", err)
   163		}
   164	
   165		state := &RepoState{
   166			Agent:            agent,
   167			Dir:              dir,
   168			ArtifactDir:      artDir,
   169			HeadBefore:       GitOutput(t, dir, "rev-parse", "HEAD"),
   170			CheckpointBefore: strings.TrimSpace(gitOutputSafe(dir, "rev-parse", checkpointReadRef())),
   171			ConsoleLog:       consoleLog,
   172		}
   173	
   174		t.Cleanup(func() {
   175			_ = consoleLog.Close()
   176			if !state.skipArtifacts {
   177				CaptureArtifacts(t, state)
   178			}
   179		})
   180	
   181		return state
   182	}
