   184	// ApplySuiteCheckpointsMode configures an arbitrary repo for the current
   185	// suite-wide E2E checkpoints mode. Useful for repos created outside SetupRepo,
   186	// such as fresh clones in remote-resume scenarios.
   187	func ApplySuiteCheckpointsMode(t *testing.T, dir string) {
   188		t.Helper()
   189	
   190		switch CheckpointsMode() {
   191		case checkpointsModeLegacy:
   192			return
   193		case checkpointsModeV2DualWrite:
   194			EnableCheckpointsV2(t, dir)
   195		case checkpointsModeV2Only:
   196			EnableCheckpointsVersion2(t, dir)
   197		default:
   198			t.Fatalf("unsupported E2E_CHECKPOINTS_MODE %q (expected legacy, v2-dual-write, or v2-only)", CheckpointsMode())
   199		}
   200	}
   201	
   202	// CheckpointsMode returns the active E2E checkpoints mode from E2E_CHECKPOINTS_MODE,
   203	// defaulting to "legacy".
   204	func CheckpointsMode() string {
   205		mode := os.Getenv("E2E_CHECKPOINTS_MODE")
   206		if mode == "" || mode == checkpointsModeLegacy {
   207			return checkpointsModeLegacy
   208		}
   209		return mode
   210	}
   211	
   212	func checkpointReadRef() string {
   213		switch CheckpointsMode() {
   214		case checkpointsModeV2DualWrite, checkpointsModeV2Only:
   215			return checkpointRefV2Main
   216		default:
   217			return checkpointRefV1
   218		}
   219	}
