   221	// CurrentCheckpointRef returns the current hash of the checkpoint ref used for
   222	// reads in the active suite mode. It fails if the ref does not exist.
   223	func CurrentCheckpointRef(t *testing.T, dir string) string {
   224		t.Helper()
   225		return GitOutput(t, dir, "rev-parse", checkpointReadRef())
   226	}
   227	
   228	// CheckpointVerifyRef returns the exact local metadata ref name tests should
   229	// use for presence checks such as rev-parse --verify.
   230	func CheckpointVerifyRef() string {
   231		switch CheckpointsMode() {
   232		case checkpointsModeLegacy:
   233			return "refs/heads/" + checkpointRefV1
   234		default:
   235			return checkpointReadRef()
   236		}
   237	}
   238	
   239	// PushCheckpointRefs pushes the checkpoint refs used by the active suite mode
   240	// to the origin remote. Remote-resume tests use this instead of hardcoding
   240	// to the origin remote. Remote-resume tests use this instead of hardcoding
   241	// legacy v1 branch pushes.
   242	func PushCheckpointRefs(t *testing.T, dir string) {
   243		t.Helper()
   244	
   245		switch CheckpointsMode() {
   246		case checkpointsModeLegacy:
   247			Git(t, dir, "push", "origin", checkpointRefV1+":"+checkpointRefV1)
   248		case checkpointsModeV2DualWrite:
   249			Git(t, dir, "push", "origin", checkpointRefV1+":"+checkpointRefV1)
   250			Git(t, dir, "push", "origin", checkpointRefV2Main+":"+checkpointRefV2Main)
   251			Git(t, dir, "push", "origin", checkpointRefV2FullCurrent+":"+checkpointRefV2FullCurrent)
   252		case checkpointsModeV2Only:
   253			Git(t, dir, "push", "origin", checkpointRefV2Main+":"+checkpointRefV2Main)
   254			Git(t, dir, "push", "origin", checkpointRefV2FullCurrent+":"+checkpointRefV2FullCurrent)
   255		default:
   256			t.Fatalf("unsupported E2E_CHECKPOINTS_MODE %q", CheckpointsMode())
   257		}
   258	
   259		if latestArchived := latestArchivedCheckpointFullRef(dir); latestArchived != "" {
   260			Git(t, dir, "push", "origin", latestArchived+":"+latestArchived)
   261		}
   262	}
   263	
   264	func latestArchivedCheckpointFullRef(dir string) string {
   265		out := strings.TrimSpace(gitOutputSafe(dir, "for-each-ref", "--format=%(refname)", checkpointRefV2FullPrefix))
   266		if out == "" {
   267			return ""
   268		}
   269	
   270		var latest string
   271		for _, ref := range strings.Split(out, "\n") {
   272			ref = strings.TrimSpace(ref)
   273			if ref == "" || ref == checkpointRefV2FullCurrent {
   274				continue
   275			}
   276			if latest == "" || ref > latest {
   277				latest = ref
   278			}
   279		}
   280		return latest
   281	}
