   283	func setupGeminiTestHome(t *testing.T, repoDir string) {
   284		t.Helper()
   285	
   286		homeDir := geminiTestHomeDir(repoDir)
   287		t.Cleanup(func() {
   288			if err := os.RemoveAll(homeDir); err != nil {
   289				t.Errorf("remove gemini test home: %v", err)
   290			}
   291		})
   292	
   293		geminiDir := filepath.Join(homeDir, ".gemini")
   294		if err := os.MkdirAll(filepath.Join(geminiDir, "acknowledgments"), 0o755); err != nil {
   295			t.Fatalf("create gemini test home: %v", err)
   296		}
   297	
   298		config := `{"security":{"auth":{"selectedType":"gemini-api-key"}}}`
   299		if err := os.WriteFile(filepath.Join(geminiDir, "settings.json"), []byte(config), 0o644); err != nil {
   300			t.Fatalf("write gemini settings: %v", err)
   301		}
   302	
   303		agentFile := filepath.Join(repoDir, ".gemini", "agents", "entire-search.md")
   304		content, err := os.ReadFile(agentFile)
   305		if err != nil {
   306			if errors.Is(err, os.ErrNotExist) {
   307				return
   308			}
   309			t.Fatalf("read gemini agent file: %v", err)
   310		}
   311	
   312		sum := sha256.Sum256(content)
   313		hash := hex.EncodeToString(sum[:])
   314	
   315		ackPath := filepath.Join(geminiDir, "acknowledgments", "agents.json")
   316		acks := map[string]map[string]string{}
   317		if data, readErr := os.ReadFile(ackPath); readErr == nil {
   318			if err := json.Unmarshal(data, &acks); err != nil {
   319				t.Fatalf("parse gemini acknowledgments: %v", err)
   320			}
   321		} else if !errors.Is(readErr, os.ErrNotExist) {
   322			t.Fatalf("read gemini acknowledgments: %v", readErr)
   323		}
   324	
   325		if acks[repoDir] == nil {
   326			acks[repoDir] = map[string]string{}
   327		}
   328		acks[repoDir]["entire-search"] = hash
   329	
   330		out, err := json.MarshalIndent(acks, "", "  ")
   331		if err != nil {
   332			t.Fatalf("marshal gemini acknowledgments: %v", err)
   333		}
   334		out = append(out, '\n')
   335	
   336		if err := os.WriteFile(ackPath, out, 0o644); err != nil {
   337			t.Fatalf("write gemini acknowledgments: %v", err)
   338		}
   339	}
