   345	func configureDroidRepoSettings(repoDir string) error {
   346		home, err := os.UserHomeDir()
   347		if err != nil {
   348			return fmt.Errorf("get home dir: %w", err)
   349		}
   350	
   351		globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
   352		repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
   353	
   354		if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
   355			return err
   356		}
   357		if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
   358			return fmt.Errorf("exclude droid settings from git: %w", err)
   359		}
   360		return nil
   361	}
   362	
   363	func mergeDroidCustomModels(globalSettingsPath, repoSettingsPath string) error {
   364		globalSettings, err := loadJSONMap(globalSettingsPath, "global droid settings")
   365		if err != nil {
   366			return err
   367		}
   368	
   369		customModels, ok := globalSettings["customModels"]
   370		if !ok {
   371			return fmt.Errorf(
   372				"global droid settings at %s missing customModels; repo-local %s shadows global settings",
   373				globalSettingsPath,
   374				repoSettingsPath,
   375			)
   376		}
   377	
   378		var models []json.RawMessage
   379		if err := json.Unmarshal(customModels, &models); err != nil {
   380			return fmt.Errorf("parse customModels in %s: %w", globalSettingsPath, err)
   381		}
   382		if len(models) == 0 {
   383			return fmt.Errorf("global droid settings at %s has empty customModels", globalSettingsPath)
   384		}
   385	
   386		repoSettings, err := loadJSONMap(repoSettingsPath, "repo-local droid settings")
   387		if err != nil {
   388			return err
   389		}
   390		repoSettings["customModels"] = customModels
   391	
   392		// Set the active custom model so interactive mode uses the BYOK model
   393		// instead of prompting for selection. The value must match the Model
   394		// field from the customModels entry (not the displayName).
   395		modelJSON, err := json.Marshal(agents.DefaultDroidModel())
   396		if err != nil {
   397			return fmt.Errorf("marshal model setting: %w", err)
   398		}
   399		repoSettings["model"] = json.RawMessage(modelJSON)
   400	
   401		// High autonomy prevents Droid from asking for confirmation during
   402		// interactive E2E tests, which would cause hangs waiting for input.
   403		repoSettings["autonomyMode"] = json.RawMessage(`"auto-high"`)
   404		repoSettings["completionSound"] = json.RawMessage(`"off"`)
   405	
   406		out, err := json.MarshalIndent(repoSettings, "", "  ")
   407		if err != nil {
   408			return fmt.Errorf("marshal repo-local droid settings: %w", err)
   409		}
   410		out = append(out, '\n')
   411	
   412		if err := os.WriteFile(repoSettingsPath, out, 0o600); err != nil {
   413			return fmt.Errorf("write repo-local droid settings %s: %w", repoSettingsPath, err)
   414		}
   415		return nil
   416	}
