   418	func loadJSONMap(path, description string) (map[string]json.RawMessage, error) {
   419		data, err := os.ReadFile(path)
   420		if err != nil {
   421			return nil, fmt.Errorf("read %s at %s: %w", description, path, err)
   422		}
   423	
   424		var parsed map[string]json.RawMessage
   425		if err := json.Unmarshal(data, &parsed); err != nil {
   426			return nil, fmt.Errorf("parse %s at %s: %w", description, path, err)
   427		}
   428		if parsed == nil {
   429			parsed = make(map[string]json.RawMessage)
   430		}
   431		return parsed, nil
   432	}
