   434	func ensureGitInfoExcludeContains(repoDir, entry string) error {
   435		excludePath := filepath.Join(repoDir, ".git", "info", "exclude")
   436	
   437		data, err := os.ReadFile(excludePath)
   438		if err != nil && !errors.Is(err, os.ErrNotExist) {
   439			return fmt.Errorf("read %s: %w", excludePath, err)
   440		}
   441	
   442		normalized := strings.ReplaceAll(string(data), "\r\n", "\n")
   443		for _, line := range strings.Split(normalized, "\n") {
   444			if strings.TrimSpace(line) == entry {
   445				return nil
   446			}
   447		}
   448	
   449		var b strings.Builder
   450		if len(data) > 0 {
   451			b.Write(data)
   452			if data[len(data)-1] != '\n' {
   453				b.WriteByte('\n')
   454			}
   455		}
   456		b.WriteString(entry)
   457		b.WriteByte('\n')
   458	
   459		if err := os.MkdirAll(filepath.Dir(excludePath), 0o755); err != nil {
   460			return fmt.Errorf("create %s: %w", filepath.Dir(excludePath), err)
   460			return fmt.Errorf("create %s: %w", filepath.Dir(excludePath), err)
   461		}
   462		if err := os.WriteFile(excludePath, []byte(b.String()), 0o644); err != nil {
   463			return fmt.Errorf("write %s: %w", excludePath, err)
   464		}
   465		return nil
   466	}
