   468	// ForEachAgent runs fn as a parallel subtest for every registered agent.
   469	// It handles repo setup, concurrency gating, context timeout, and cleanup.
   470	// The timeout is scaled by each agent's TimeoutMultiplier.
   471	//
   472	// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
   473	// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
   474	// panic and restarts the entire scenario with a fresh repository, up to
   475	// maxScenarioRestarts times. This avoids stale CLI session state from the
   476	// failed attempt poisoning the retry.
   477	func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
   478		t.Helper()
   479		t.Parallel()
   480		all := agents.All()
   481		if len(all) == 0 {
   482			t.Skip("no agents registered (check E2E_AGENT filter)")
   483		}
   484		runForAgents(t, all, timeout, fn)
   485	}
   486	
   487	// ForEachNamedAgent runs fn as a parallel subtest for each registered agent
   488	// whose name matches one of the provided names.
   489	func ForEachNamedAgent(t *testing.T, timeout time.Duration, names []string, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
   490		t.Helper()
   491		t.Parallel()
   492	
   493		allowed := make(map[string]struct{}, len(names))
   494		for _, name := range names {
   495			allowed[name] = struct{}{}
   496		}
   497	
   498		var selected []agents.Agent
   499		for _, agent := range agents.All() {
   500			if _, ok := allowed[agent.Name()]; ok {
   501				selected = append(selected, agent)
   502			}
   503		}
   504		if len(selected) == 0 {
   505			t.Skip("no matching agents registered (check E2E_AGENT filter)")
   506		}
   507	
   508		runForAgents(t, selected, timeout, fn)
   509	}
   510	
   511	func runForAgents(t *testing.T, all []agents.Agent, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
   512		t.Helper()
   513		for _, agent := range all {
   514			t.Run(agent.Name(), func(t *testing.T) {
   515				// Use the global test deadline for slot wait so we don't
   516				// skip prematurely — only bail if the whole binary is dying.
   517				slotCtx := context.Background()
   518				if deadline, ok := t.Deadline(); ok {
   519					var cancel context.CancelFunc
   520					slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
   521					defer cancel()
   522				}
   523				if err := agents.AcquireSlot(slotCtx, agent); err != nil {
   524					t.Fatalf("timed out waiting for agent slot: %v", err)
   525				}
   526				defer agents.ReleaseSlot(agent)
   527	
   528				// Per-test timeout starts after slot is acquired, scaled
   529				// by the agent's multiplier (e.g. 2.5× for gemini).
   530				scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
   531	
   532				var prevState *RepoState
   533				for attempt := range maxScenarioRestarts + 1 {
   534					s := SetupRepo(t, agent)
   535					ctx, cancel := context.WithTimeout(context.Background(), scaled)
   536	
   537					// On restart, suppress artifact capture from the previous
   538					// failed attempt so it doesn't overwrite the final one.
   539					if prevState != nil {
   540						prevState.skipArtifacts = true
   541					}
   542	
   543					restarted := runScenario(t, s, ctx, fn)
   544					cancel()
   545	
   546					if !restarted {
   547						return
   548					}
   549					prevState = s
   550					if attempt >= maxScenarioRestarts {
   551						t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
   552					}
   553					t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
   554				}
   555			})
   556		}
   557	}
   558	
   559	// runScenario runs the test function and recovers from errScenarioRestart
   560	// panics triggered by transient API errors in RunPrompt. Returns true if
   561	// the scenario should be restarted with a fresh repository.
   562	func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
   563		t.Helper()
   564		defer func() {
   565			if r := recover(); r != nil {
   566				if _, ok := r.(errScenarioRestart); ok {
   567					restarted = true
   568					return
   569				}
   570				panic(r) // re-panic for unexpected panics
   571			}
   572		}()
   573		fn(t, s, ctx)
   574		return false
   575	}
   576	
   577	const maxScenarioRestarts = 2 // restart up to 2 times = 3 total attempts
   578	
   579	// errScenarioRestart is panicked by RunPrompt when a transient API error is
   580	// detected. ForEachAgent recovers from this panic and restarts the test
   581	// scenario with a fresh repository, avoiding stale CLI state from the failed
   582	// attempt.
   583	type errScenarioRestart struct {
   584		msg string
   585	}
   586	
   587	// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
   588	// and returns the result. If the agent reports a transient API error, it
   589	// panics with errScenarioRestart to trigger a full scenario restart in
   590	// ForEachAgent (see runScenario).
   591	func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
   592		t.Helper()
   593		out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
   594		s.logPromptResult(out)
   595	
   596		if err != nil && s.Agent.IsTransientError(out, err) {
   597			errMsg := fmt.Sprintf("transient API error (stderr: %s)", strings.TrimSpace(out.Stderr))
   598			t.Logf("%s — restarting scenario", errMsg)
   599			fmt.Fprintf(s.ConsoleLog, "> [transient] %s — restarting scenario\n", errMsg)
   600			panic(errScenarioRestart{msg: errMsg})
   601		}
   602	
   603		return out, err
   604	}
   605	
   606	func (s *RepoState) logPromptResult(out agents.Output) {
   607		s.ConsoleLog.WriteString("> " + out.Command + "\n")
   608		s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
   609		s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
   610	}
   611	
   612	// Git runs a git command in the repo and logs it to ConsoleLog.
   613	func (s *RepoState) Git(t *testing.T, args ...string) {
   614		t.Helper()
   615		s.ConsoleLog.WriteString("> git " + strings.Join(args, " ") + "\n")
   616		Git(t, s.Dir, args...)
   617	}
