   619	// StartSession starts an interactive session and registers it for pane
   620	// capture in artifacts. Returns nil if the agent does not support interactive
   621	// mode. The session is closed automatically during test cleanup.
   622	func (s *RepoState) StartSession(t *testing.T, ctx context.Context) agents.Session {
   623		t.Helper()
   624		session, err := s.Agent.StartSession(ctx, s.Dir)
   625		if err != nil {
   626			t.Fatalf("start session: %v", err)
   627		}
   628		if session == nil {
   629			return nil
   630		}
   631		s.session = session
   632		return session
   633	}
   634	
   635	// WaitFor waits for a pattern in the interactive session's pane and logs the
   636	// pane content to ConsoleLog after the wait completes (success or failure).
   637	func (s *RepoState) WaitFor(t *testing.T, session agents.Session, pattern string, timeout time.Duration) {
