   357	// ForEachAgent runs fn as a parallel subtest for every registered agent.
   358	// It handles repo setup, concurrency gating, context timeout, and cleanup.
   359	// The timeout is scaled by each agent's TimeoutMultiplier.
   360	//
   361	// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
   362	// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
   363	// panic and restarts the entire scenario with a fresh repository, up to
   364	// maxScenarioRestarts times. This avoids stale CLI session state from the
   365	// failed attempt poisoning the retry.
   366	func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
   367		t.Helper()
   368		t.Parallel()
   369		all := agents.All()
   370		if len(all) == 0 {
   371			t.Skip("no agents registered (check E2E_AGENT filter)")
   372		}
   373		for _, agent := range all {
   374			t.Run(agent.Name(), func(t *testing.T) {
   375				// Use the global test deadline for slot wait so we don't
   376				// skip prematurely — only bail if the whole binary is dying.
   377				slotCtx := context.Background()
   378				if deadline, ok := t.Deadline(); ok {
   379					var cancel context.CancelFunc
   380					slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
   381					defer cancel()
   382				}
   383				if err := agents.AcquireSlot(slotCtx, agent); err != nil {
   384					t.Fatalf("timed out waiting for agent slot: %v", err)
   385				}
   386				defer agents.ReleaseSlot(agent)
   387	
   388				// Per-test timeout starts after slot is acquired, scaled
   389				// by the agent's multiplier (e.g. 2.5× for gemini).
   390				scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
   391	
   392				var prevState *RepoState
   393				for attempt := range maxScenarioRestarts + 1 {
   394					s := SetupRepo(t, agent)
   395					ctx, cancel := context.WithTimeout(context.Background(), scaled)
   396	
   397					// On restart, suppress artifact capture from the previous
   398					// failed attempt so it doesn't overwrite the final one.
   399					if prevState != nil {
   400						prevState.skipArtifacts = true
   401					}
   402	
   403					restarted := runScenario(t, s, ctx, fn)
   404					cancel()
   405	
   406					if !restarted {
   407						return
   408					}
   409					prevState = s
   410					if attempt >= maxScenarioRestarts {
   411						t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
   412					}
   413					t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
   414				}
   415			})
   416		}
   417	}
