   419	// runScenario runs the test function and recovers from errScenarioRestart
   420	// panics triggered by transient API errors in RunPrompt. Returns true if
   421	// the scenario should be restarted with a fresh repository.
   422	func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
   423		t.Helper()
   424		defer func() {
   425			if r := recover(); r != nil {
   426				if _, ok := r.(errScenarioRestart); ok {
   427					restarted = true
   428					return
   429				}
   430				panic(r) // re-panic for unexpected panics
   431			}
   432		}()
   433		fn(t, s, ctx)
   434		return false
   435	}
